-- FAKE DATA ONLY. A bigger dataset for testing: 40 rooms, 8 room types, ~300 guests, 10 travel agents, ~1,100 bookings.
-- Self-contained: creates its OWN database `frontdesk_ai_large` (the small `frontdesk_ai` database is not touched).
-- To use it: run this file, then set DB_NAME=frontdesk_ai_large in backend/.env and restart the backend.
-- To go back: set DB_NAME=frontdesk_ai again. Re-running this file resets the large database.
-- "Today" in this data is 2026-10-04 (keep APP_TODAY=2026-10-04). Generated with a fixed random seed.
DROP DATABASE IF EXISTS frontdesk_ai_large;
CREATE DATABASE frontdesk_ai_large CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE frontdesk_ai_large;

CREATE TABLE room_types (
  id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255),
  max_guests TINYINT NOT NULL, base_rate DECIMAL(10,2) NOT NULL);
CREATE TABLE rooms (
  id INT AUTO_INCREMENT PRIMARY KEY, room_number VARCHAR(10) NOT NULL UNIQUE, room_type_id INT NOT NULL,
  status ENUM('available','occupied','cleaning','maintenance') NOT NULL DEFAULT 'available',
  FOREIGN KEY (room_type_id) REFERENCES room_types(id));
CREATE TABLE rates (
  id INT AUTO_INCREMENT PRIMARY KEY, room_type_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL,
  rate DECIMAL(10,2) NOT NULL, label VARCHAR(50),
  FOREIGN KEY (room_type_id) REFERENCES room_types(id), CHECK (end_date >= start_date));
CREATE TABLE guests (
  id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, phone VARCHAR(30), email VARCHAR(100));
CREATE TABLE travel_agents (
  id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, contact_email VARCHAR(100));
CREATE TABLE bookings (
  id INT AUTO_INCREMENT PRIMARY KEY, booking_ref VARCHAR(20) NOT NULL UNIQUE, guest_id INT NULL, travel_agent_id INT NULL,
  room_type_id INT NOT NULL, room_id INT NULL, check_in DATE NOT NULL, check_out DATE NOT NULL, num_guests TINYINT NOT NULL DEFAULT 1,
  source ENUM('walk_in','phone','email','whatsapp','travel_agent','direct_website','ota') NOT NULL,
  status ENUM('blocked','confirmed','cancelled','checked_in','checked_out') NOT NULL,
  payment_status ENUM('unpaid','paid') NOT NULL DEFAULT 'unpaid', total_amount DECIMAL(10,2) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at DATETIME NULL, cancelled_at DATETIME NULL,
  FOREIGN KEY (guest_id) REFERENCES guests(id), FOREIGN KEY (travel_agent_id) REFERENCES travel_agents(id),
  FOREIGN KEY (room_type_id) REFERENCES room_types(id), FOREIGN KEY (room_id) REFERENCES rooms(id),
  CHECK (check_out > check_in), INDEX idx_availability (room_type_id, status, check_in, check_out));
CREATE TABLE ai_audit_log (
  id INT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, staff_user VARCHAR(50),
  user_message TEXT NOT NULL, parsed_request TEXT, db_result TEXT, reply_text TEXT, validator_passed TINYINT(1));



-- Rates: weekend rules have the lowest ids, then school holiday, year-end, Christmas. The highest matching id wins.



